local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local player = Players.LocalPlayer;
local playerGui = player:WaitForChild("PlayerGui")
if playerGui:FindFirstChild("VoidHub") then
playerGui:FindFirstChild("VoidHub"):Destroy()
end;
local screenGui = Instance.new("ScreenGui")
screenGui.Name = "VoidHub"
screenGui.Parent = playerGui;
screenGui.ResetOnSpawn = false;
local frame = Instance.new("Frame")
frame.Size = UDim2.new(0, 350, 0, 280)
frame.Position = UDim2.new(0.5, -175, 0.5, -140)
frame.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
frame.BorderColor3 = Color3.fromRGB(255, 50, 50)
frame.BorderSizePixel = 2;
frame.Parent = screenGui;
local corner = Instance.new("UICorner")
corner.CornerRadius = UDim.new(0, 10)
corner.Parent = frame;
local dragging, dragInput, dragStart, startPos;
local function update(input)
local delta = input.Position - dragStart;
frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
end;
frame.InputBegan:Connect(function(input)
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
dragging = true;
dragStart = input.Position;
startPos = frame.Position;
input.Changed:Connect(function()
if input.UserInputState == Enum.UserInputState.End then
dragging = false
end
end)
end
end)
frame.InputChanged:Connect(function(input)
if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
dragInput = input
end
end)
UserInputService.InputChanged:Connect(function(input)
if input == dragInput and dragging then
update(input)
end
end)
local title = Instance.new("TextLabel")
title.Size = UDim2.new(1, -40, 0, 35)
title.Position = UDim2.new(0, 10, 0, 5)
title.BackgroundTransparency = 1;
title.Text = "حياة السجن"
title.TextColor3 = Color3.fromRGB(255, 100, 100)
title.TextSize = 20;
title.Font = Enum.Font.GothamBold;
title.Parent = frame;
local closeButton = Instance.new("TextButton")
closeButton.Size = UDim2.new(0, 30, 0, 30)
closeButton.Position = UDim2.new(1, -35, 0, 5)
closeButton.BackgroundColor3 = Color3.fromRGB(255, 50, 50)
closeButton.Text = "X"
closeButton.TextColor3 = Color3.fromRGB(255, 255, 255)
closeButton.TextSize = 16;
closeButton.Font = Enum.Font.GothamBold;
closeButton.Parent = frame;
local closeCorner = Instance.new("UICorner")
closeCorner.CornerRadius = UDim.new(0, 6)
closeCorner.Parent = closeButton;
closeButton.MouseButton1Click:Connect(function()
screenGui:Destroy()
end)
local statusLabel = Instance.new("TextLabel")
statusLabel.Size = UDim2.new(1, -20, 0, 20)
statusLabel.Position = UDim2.new(0, 10, 0, 250)
statusLabel.BackgroundTransparency = 1;
statusLabel.Text = "جاهز"
statusLabel.TextColor3 = Color3.fromRGB(100, 255, 100)
statusLabel.TextSize = 12;
statusLabel.Font = Enum.Font.Gotham;
statusLabel.Parent = frame;
local function updateStatus(message, color)
statusLabel.Text = message;
statusLabel.TextColor3 = color or Color3.fromRGB(255, 255, 255)
spawn(function()
wait(3)
statusLabel.Text = "جاهز"
statusLabel.TextColor3 = Color3.fromRGB(100, 255, 100)
end)
end;
local function teleportToCriminalBase()
updateStatus("Teleporting to Crim Base...", Color3.fromRGB(255, 255, 100))
local character = player.Character;
if not character or not character:FindFirstChild("HumanoidRootPart") then
updateStatus("Character not found", Color3.fromRGB(255, 100, 100))
return
end;
spawn(function()
character.HumanoidRootPart.CFrame = CFrame.new(-943, 95, 2055)
updateStatus("Teleported to Crim Base!", Color3.fromRGB(100, 255, 100))
end)
end;
local function teleportToPrison()
updateStatus("Teleporting to Prison...", Color3.fromRGB(255, 255, 100))
local character = player.Character;
if not character or not character:FindFirstChild("HumanoidRootPart") then
updateStatus("Character not found", Color3.fromRGB(255, 100, 100))
return
end;
spawn(function()
character.HumanoidRootPart.CFrame = CFrame.new(916, 98, 2379)
updateStatus("Teleported to Prison!", Color3.fromRGB(100, 255, 100))
end)
end;
local function teleportToGuardsRoom()
updateStatus("Teleporting to Guards Room...", Color3.fromRGB(255, 255, 100))
local character = player.Character;
if not character or not character:FindFirstChild("HumanoidRootPart") then
updateStatus("Character not found", Color3.fromRGB(255, 100, 100))
return
end;
spawn(function()
character.HumanoidRootPart.CFrame = CFrame.new(919, 98, 2138)
updateStatus("Teleported to Guards Room!", Color3.fromRGB(100, 255, 100))
end)
end;
local noclipEnabled = false;
local noclipConnection = nil;
local function toggleNoclip()
local character = player.Character;
if not character then
updateStatus("Character not found", Color3.fromRGB(255, 100, 100))
return
end;
noclipEnabled = not noclipEnabled;
if noclipEnabled then
updateStatus("Noclip ON", Color3.fromRGB(100, 255, 100))
if noclipConnection then
noclipConnection:Disconnect()
end;
noclipConnection = RunService.Stepped:Connect(function()
pcall(function()
for _, part in pairs(character:GetChildren()) do
if part:IsA("BasePart") then
part.CanCollide = false
end
end
end)
end)
else
updateStatus("Noclip OFF", Color3.fromRGB(255, 100, 100))
if noclipConnection then
noclipConnection:Disconnect()
noclipConnection = nil
end;
pcall(function()
for _, part in pairs(character:GetChildren()) do
if part:IsA("BasePart") then
if part.Name == "HumanoidRootPart" then
part.CanCollide = false
else
part.CanCollide = true
end
end
end
end)
end
end;
local function createButton(text, position, callback)
local button = Instance.new("TextButton")
button.Size = UDim2.new(1, -20, 0, 35)
button.Position = position;
button.BackgroundColor3 = Color3.fromRGB(45, 45, 45)
button.Text = text;
button.TextColor3 = Color3.fromRGB(255, 255, 255)
button.TextSize = 14;
button.Font = Enum.Font.Gotham;
button.Parent = frame;
local buttonCorner = Instance.new("UICorner")
buttonCorner.CornerRadius = UDim.new(0, 8)
buttonCorner.Parent = button;
button.MouseEnter:Connect(function()
button.BackgroundColor3 = Color3.fromRGB(255, 50, 50)
end)
button.MouseLeave:Connect(function()
button.BackgroundColor3 = Color3.fromRGB(45, 45, 45)
end)
button.MouseButton1Click:Connect(callback)
return button
end;
createButton("السلاح", UDim2.new(0, 10, 0, 50), function()
teleportToCriminalBase()
end)
createButton("اذهب الى السجن", UDim2.new(0, 10, 0, 95), function()
teleportToPrison()
end)
createButton("غرفة حراسة جوتو", UDim2.new(0, 10, 0, 140), function()
teleportToGuardsRoom()
end)
local noclipButton = createButton("تشتغل اختراقالجدران ", UDim2.new(0, 10, 0, 185), function()
toggleNoclip()
if noclipEnabled then
noclipButton.Text = "اختراقالجدران: تشغيل"
noclipButton.BackgroundColor3 = Color3.fromRGB(0, 150, 0)
else
noclipButton.Text = "ايقاف: اختراق الجدران "
noclipButton.BackgroundColor3 = Color3.fromRGB(45, 45, 45)
end
end)
